use serde::{Deserialize, Serialize};
#[cfg(windows)]
use std::time::Instant;
use crate::canonical::{canonical_hash, normalize};
use crate::graph::{ComputationGraph, Op};

#[cfg(windows)]
use crate::jit_x86::JitFunction;

/// Detailed result of multi-agent verification and execution
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct VerificationResult {
    /// Canonical Blake3 hash of graph generated by Agent A (hex)
    pub agent_a_hash: String,
    /// Canonical Blake3 hash of graph optimized by Agent B (hex)
    pub agent_b_hash: String,
    /// Indicates whether canonical hashes match (proven semantic equivalence)
    pub hashes_match: bool,
    /// List of optimizations applied during normalization
    pub optimizations_applied: Vec<String>,
    /// Native JIT execution result (if compiled successfully)
    pub jit_result: Option<i64>,
    /// Machine code native execution time in nanoseconds
    pub jit_time_ns: Option<u128>,
}

/// Simulates full multi-agent composition pipeline:
/// 1. Agent A (Generation): parse SSA graph from AI-generated JSON
/// 2. Agent B (Optimization): normalization, constant folding, dead-code elimination, CSE
/// 3. Agent C (Audit/Verification): isomorphism proof via Blake3
/// 4. JIT Execution: direct compilation to native x86-64 and execution in nanoseconds
pub fn simulate_multi_agent_pipeline(
    raw_json: &str,
    _inputs: &[i64],
) -> Result<VerificationResult, String> {
    // 1. Agent A: JSON parsing
    let graph_a = ComputationGraph::from_json(raw_json)
        .map_err(|e| format!("Error parsing JSON from Agent A: {}", e))?;
    graph_a.validate_invariants()?;

    let hash_a_bytes = canonical_hash(&graph_a);
    let hash_a_hex = hex_encode(&hash_a_bytes);

    // 2. Agent B: Canonical Optimization
    let initial_node_count = graph_a.nodes.len();
    let graph_b = normalize(&graph_a);
    let final_node_count = graph_b.nodes.len();

    let mut optimizations = Vec::new();
    if final_node_count < initial_node_count {
        optimizations.push(format!(
            "Dead Code Elimination & Constant Folding: Nodes reduced from {} to {}",
            initial_node_count, final_node_count
        ));
    }

    let has_folded_consts = graph_b
        .nodes
        .iter()
        .any(|n| matches!(n.op, Op::ConstI64(_)))
        && graph_a
            .nodes
            .iter()
            .any(|n| matches!(n.op, Op::Add(_, _) | Op::Mul(_, _)));
    if has_folded_consts {
        optimizations.push("Constant Folding applied to literal operations".to_string());
    }

    let hash_b_bytes = canonical_hash(&graph_b);
    let hash_b_hex = hex_encode(&hash_b_bytes);

    let hashes_match = hash_a_hex == hash_b_hex;

    // 3 & 4. Agent C / JIT Execution
    #[cfg(windows)]
    let (jit_result, jit_time_ns) = {
        let jit = JitFunction::compile(&graph_b)?;

        // Nanosecond measurement of CPU native execution
        let start = Instant::now();
        let res = jit.execute(_inputs);
        let elapsed_ns = start.elapsed().as_nanos();

        (Some(res), Some(elapsed_ns))
    };

    #[cfg(not(windows))]
    let (jit_result, jit_time_ns) = (None, None);

    Ok(VerificationResult {
        agent_a_hash: hash_a_hex,
        agent_b_hash: hash_b_hex,
        hashes_match,
        optimizations_applied: optimizations,
        jit_result,
        jit_time_ns,
    })
}

/// Generates official JSON Schema for VERA v2 graph format for LLM specifications
pub fn generate_json_schema() -> String {
    serde_json::json!({
        "$schema": "http://json-schema.org/draft-07/schema#",
        "title": "VeraComputationGraph",
        "description": "VERA Engine v2 Canonical SSA Graph Format for AI Agents",
        "type": "object",
        "properties": {
            "nodes": {
                "type": "array",
                "items": {
                    "type": "object",
                    "properties": {
                        "id": { "type": "integer", "minimum": 0 },
                        "op": {
                            "description": "Atomic SSA operation",
                            "oneOf": [
                                { "type": "object", "properties": { "Input": { "type": "integer", "minimum": 0 } }, "required": ["Input"] },
                                { "type": "object", "properties": { "ConstI64": { "type": "integer" } }, "required": ["ConstI64"] },
                                { "type": "object", "properties": { "Add": { "type": "array", "items": { "type": "integer" }, "minItems": 2, "maxItems": 2 } }, "required": ["Add"] },
                                { "type": "object", "properties": { "Sub": { "type": "array", "items": { "type": "integer" }, "minItems": 2, "maxItems": 2 } }, "required": ["Sub"] },
                                { "type": "object", "properties": { "Mul": { "type": "array", "items": { "type": "integer" }, "minItems": 2, "maxItems": 2 } }, "required": ["Mul"] },
                                { "type": "object", "properties": { "Div": { "type": "array", "items": { "type": "integer" }, "minItems": 2, "maxItems": 2 } }, "required": ["Div"] },
                                { "type": "object", "properties": { "And": { "type": "array", "items": { "type": "integer" }, "minItems": 2, "maxItems": 2 } }, "required": ["And"] },
                                { "type": "object", "properties": { "Or": { "type": "array", "items": { "type": "integer" }, "minItems": 2, "maxItems": 2 } }, "required": ["Or"] },
                                { "type": "object", "properties": { "Xor": { "type": "array", "items": { "type": "integer" }, "minItems": 2, "maxItems": 2 } }, "required": ["Xor"] },
                                {
                                    "type": "object",
                                    "properties": {
                                        "Select": {
                                            "type": "object",
                                            "properties": {
                                                "cond": { "type": "integer" },
                                                "if_true": { "type": "integer" },
                                                "if_false": { "type": "integer" }
                                            },
                                            "required": ["cond", "if_true", "if_false"]
                                        }
                                    },
                                    "required": ["Select"]
                                },
                                { "type": "object", "properties": { "Output": { "type": "integer" } }, "required": ["Output"] }
                            ]
                        }
                    },
                    "required": ["id", "op"]
                }
            }
        },
        "required": ["nodes"]
    }).to_string()
}

fn hex_encode(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{:02x}", b)).collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_multi_agent_pipeline_basic() {
        let mut g = ComputationGraph::new();
        let a = g.add_input(0);
        let b = g.add_input(1);
        let sum = g.add_add(a, b);
        let c10 = g.add_const(10);
        let mul = g.add_mul(sum, c10);
        g.set_output(mul);

        let json = g.to_json();
        let result = simulate_multi_agent_pipeline(&json, &[5, 3])
            .expect("Multi-agent pipeline must execute successfully");

        assert!(result.hashes_match);
        #[cfg(windows)]
        {
            assert_eq!(result.jit_result, Some((5 + 3) * 10));
            assert!(result.jit_time_ns.is_some());
        }
        #[cfg(not(windows))]
        {
            assert_eq!(result.jit_result, None);
        }
    }

    #[test]
    fn test_json_schema_generation() {
        let schema = generate_json_schema();
        let parsed: serde_json::Value = serde_json::from_str(&schema).expect("Schema must be valid JSON");
        assert_eq!(parsed["title"], "VeraComputationGraph");
    }

    #[test]
    fn test_different_agents_same_result() {
        // Agent A creates: (x * 2) + (x * 2)
        let mut g1 = ComputationGraph::new();
        let x1 = g1.add_input(0);
        let c2_1 = g1.add_const(2);
        let p1_1 = g1.add_mul(x1, c2_1);
        let p1_2 = g1.add_mul(x1, c2_1);
        let s1 = g1.add_add(p1_1, p1_2);
        g1.set_output(s1);

        // Agent B creates: (2 * x) * 2
        let mut g2 = ComputationGraph::new();
        let c2_2 = g2.add_const(2);
        let x2 = g2.add_input(0);
        let p2_1 = g2.add_mul(c2_2, x2);
        let c2_3 = g2.add_const(2);
        let p2_2 = g2.add_mul(p2_1, c2_3);
        g2.set_output(p2_2);

        // Both with x = 7 must compute 28
        let r1 = simulate_multi_agent_pipeline(&g1.to_json(), &[7]).unwrap();
        let r2 = simulate_multi_agent_pipeline(&g2.to_json(), &[7]).unwrap();

        #[cfg(windows)]
        {
            assert_eq!(r1.jit_result, Some(28));
            assert_eq!(r2.jit_result, Some(28));
        }
        #[cfg(not(windows))]
        {
            assert_eq!(r1.jit_result, None);
            assert_eq!(r2.jit_result, None);
        }
    }
}
